"""Complete the eighteen Player's Guide Oblivion powers (not Ceremonies)."""
import json,re,runpy,sys
from pathlib import Path
repo=Path(__file__).resolve().parent.parent;work=Path(sys.argv[1])
shared=runpy.run_path(str(repo/'scripts/review-chicago-oblivion.py'))
manifest=shared['manifest'];extract=shared['extract'];sections=shared['sections']
candidates=json.loads((work/'catalog/candidates.json').read_text(encoding='utf-8'))
data=[
 ('Ashes to Ashes','Cinzas às Cinzas',1,[87],{},[
 ('Descrição','Destrói as evidências de alimentação ao introduzir vitae num cadáver recente ou antigo. Não funciona em vampiros; cadáveres animados podem ser afetados a critério do Narrador.'),('Custo','Um Teste de Sangue.'),('Parada','O cabeçalho da fonte indica Vigor + Oblívio contra Vigor + Medicina ou Fortitude. No Sistema, o cadáver animado resiste com Vigor, ou Vigor + Fortitude se possuir essa Disciplina. A divergência do cabeçalho é preservada, sem presumir uma correção.'),('Sistema','O vampiro paga o custo e introduz a vitae no cadáver. Um corpo não animado se desintegra em três turnos, sem teste adicional. Contra um cadáver animado, disputa Vigor + Oblívio contra a resistência indicada no Sistema acima. Se vencer, o corpo se dissolve em cinco turnos menos a margem, mínimo de um; enquanto se desintegra, sofre Debilitação física. Uma vitória crítica o desintegra imediatamente. Numa falha total, aquele cadáver fica imune ao poder de qualquer usuário.'),('Duração','Variável, conforme o resultado e a animação do cadáver.')]),
 ('The Binding Fetter','A Âncora Vinculante',1,[87],{},[
 ('Descrição','Identifica objetos, locais e até pessoas importantes para fantasmas, suas âncoras de existência. Conhecê-las permite ao necromante manipular melhor o espírito. As auras podem irradiar vitalidade e luz dourada, decadência ou cheiros significativos, como pão recém-assado, gasolina ou fumaça de cigarro.'),('Custo','Gratuito.'),('Parada','Raciocínio + Oblívio, conforme o cabeçalho. O Sistema não determina uma Dificuldade nem exige explicitamente um teste de ativação.'),('Sistema','Os sentidos ficam afinados às energias das âncoras, identificando suas auras por visão, olfato e outros sentidos. O vampiro fica distraído e sofre uma penalidade de dois dados em testes de Destreza e Raciocínio enquanto mantiver o poder.'),('Duração','Uma cena.')]),
 ('Fatal Prediction','Predição Fatal',2,[89],{'Auspícios':2},[
 ('Descrição','O vampiro liga fios invisíveis de entropia a um mortal, aumentando a possibilidade de dano ou morte durante a noite e o dia seguintes. Não pode interferir com a vítima sem arriscar romper o efeito.'),('Custo','Um Teste de Sangue.'),('Parada','Determinação + Oblívio contra Raciocínio + Ocultismo da vítima.'),('Sistema','Cada sucesso de margem causa um ponto de dano agravado à vítima em algum momento das próximas 24 horas. A causa pode ser uma doença repentina ou um acidente improvável. O vampiro não deve interagir direta ou indiretamente com o alvo, pois isso pode anular o poder. O Narrador define o limite da interação indireta; enviar subordinados para apressar o resultado certamente viola essa condição. O uso é invisível, mas uma testemunha pode perceber indícios de algo sinistro com Raciocínio + Ocultismo, Dificuldade 3. Só mortais, incluindo carniçais, são afetados; vampiros já estão mortos e resistem a essa manipulação da entropia.'),('Duração','Uma noite e um dia: 24 horas.')]),
 ('Where the Veil Thins','Onde o Véu se Afina',2,[89,90],{},[
 ('Descrição','Percebe onde o véu entre vivos e mortos é mais fino, sem revelar por que isso acontece. Nos locais mais tênues, a saúde dos mortais sofre e Oblívio se torna mais fácil.'),('Custo','Um Teste de Sangue.'),('Parada','Inteligência + Oblívio, Dificuldade 3.'),('Sistema','Após pagar o custo, uma vitória revela a densidade do véu nas proximidades, até a extensão de um edifício ou marco geográfico inteiro. Uma vitória crítica também revela se a densidade mudou recentemente. Numa falha total, o poder fornece uma leitura falsa. Sem usar este poder, o praticante não se beneficia do véu tênue, embora penalidades possam ser aplicadas a critério do Narrador.'),('Densidade do Véu','| Densidade | Causas possíveis | Efeito |\n| --- | --- | --- |\n| Impenetrável | Nenhuma morte no local; solo sagrado | Fantasmas não podem atravessar aqui |\n| Espesso | Morte antiga; lugar de alegria | Nenhum efeito |\n| Fino | Morte recente; passagem de mortais melancólicos | −1 na Dificuldade de testes de Cerimônias de Oblívio |\n| Desgastado | Série de mortes; Cerimônias frequentes | −2 na Dificuldade de testes de Cerimônias de Oblívio |\n| Ausente | Uso de Romper o Véu; travessia frequente de aparições | −2 na Dificuldade de Cerimônias; aparições passam livremente entre os mundos; mortais sofrem dois danos superficiais à Vitalidade, que não podem curar até sair |'),('Duração','Um turno.')]),
 ('Aura of Decay','Aura de Decadência',3,[90],{},[
 ('Descrição','A conexão com Oblívio faz plantas murcharem, animais e humanos adoecerem e alimentos estragarem. O texto afirma que não acelera a decomposição de coisas mortas; o Sistema, entretanto, também inclui efeitos em materiais inorgânicos, como tijolos. Essas duas afirmações da fonte são mantidas.'),('Custo','Um Teste de Sangue.'),('Parada','Vigor + Oblívio, Dificuldade 3 para ativar. O cabeçalho lista resistência de Vigor + Medicina ou Fortitude; o Sistema descreve a disputa de seres vivos como Vigor + Medicina. Nenhuma resistência adicional foi inventada para resolver essa diferença.'),('Sistema','Após pagar o custo e vencer o teste de ativação, materiais orgânicos e inorgânicos não inteligentes a até cinco metros sofrem deterioração: plantas morrem, comida apodrece e tijolos começam a ruir. Alimentos e água afetados podem se tornar tóxicos. Consumir esse material causa dois danos superficiais à Vitalidade na cena seguinte e em cada cena posterior até um tratamento com Inteligência + Medicina, Dificuldade 3.\n\nSeres vivos na aura disputam Vigor + Medicina contra o teste de ativação do vampiro. Cada ponto de margem do vampiro causa um dano superficial à Vitalidade, sem redução pela metade, aplicado gradualmente durante a cena. Reaplicar o poder na mesma cena não causa novo dano à Vitalidade de mortais já afetados. Quem tem olfato percebe o odor de podridão emanado do vampiro, que sofre uma penalidade de dois dados em todos os testes sociais enquanto a aura estiver ativa.'),('Duração','Uma cena.')]),
 ('Passion Feast','Banquete de Paixões',3,[90,91],{'Fortitude':2},[
 ('Descrição','Permite subsistir das paixões de aparições em vez de sangue, seja para permanecer no mundo dos mortos, seja para atormentar um espírito.'),('Custo','Gratuito.'),('Parada','Determinação + Oblívio contra Determinação + Autocontrole da aparição.'),('Sistema','A até três metros da aparição, o vampiro disputa as paradas indicadas. Se vencer, causa um dano agravado à Força de Vontade da aparição e reduz sua própria Fome em um. O Narrador pode atribuir uma Mácula: consumir a paixão enfraquece a razão de existir do espírito e pode levá-lo à autodestruição. O Narrador determina quantas paixões a aparição possui; cinco ou mais são raras. Quando todas são consumidas, pode decidir que o espírito se torna um espectro assassino e incontrolável.'),('Duração','Passivo.')]),
 ('Shadow Servant','Servo Sombrio',3,[91],{'Auspícios':1},[
 ('Descrição','O vampiro dá vida independente a parte da própria sombra para espionar ou inquietar inimigos.'),('Custo','Um Teste de Sangue.'),('Parada','Nenhuma para ativar; Raciocínio + Oblívio, Dificuldade 3, para evitar luz forte por um turno.'),('Sistema','O servo não tem mente própria e segue comandos mentais do criador. Move-se em velocidade de corrida, passa sob portas, escala paredes e atravessa frestas minúsculas, mas não suporta áreas muito iluminadas. Pode agarrar-se a veículos em movimento; seu alcance se limita à distância que consegue percorrer numa noite. Vê e ouve os arredores e transmite as informações assim que é reabsorvido pela sombra do criador. Apenas luz forte, como uma lanterna potente ou luz diurna, pode bani-lo; o teste indicado permite evitá-la por um turno.'),('Duração','Uma cena.')]),
 ('Necrotic Plague','Praga Necrótica',4,[91,92],{},[
 ('Descrição','Pelo toque, o vampiro envenena o sangue de uma vítima mortal com uma doença sobrenatural. Pode torná-la contagiosa. Conhecimento de Medicina permite imitar doenças específicas, inclusive algumas consideradas extintas.'),('Custo','Um Teste de Sangue.'),('Parada','Inteligência + Oblívio contra a resistência da vítima. O cabeçalho apresenta Vigor + Vigor ou Fortitude; o Sistema especifica um teste de Vigor, ou Vigor + Fortitude para quem possui a Disciplina. O texto da fonte é preservado sem automatizar uma escolha entre essas redações.'),('Sistema','O vampiro paga o custo e rola Inteligência + Oblívio enquanto toca a vítima mortal. Alvos debilitados — bebês, idosos, doentes, convalescentes, moribundos ou com três ou menos caixas de Vitalidade não marcadas — são infectados automaticamente. Alvos saudáveis fazem a resistência descrita no Sistema; só evitam a doença se obtiverem mais sucessos que o vampiro.\n\nA vítima sofre um dano agravado à Vitalidade no início de cada cena após a infecção, durante um número de cenas igual ao nível de Oblívio do usuário. Tratamento médico não cura esse dano sobrenatural, mas beber vitae pode curá-lo. Numa vitória crítica, o usuário pode tornar a doença transmissível por toque. Cada novo infectado sofre a doença por um turno a menos que quem o infectou: essa é a unidade usada pela fonte, embora a duração principal esteja em cenas. O Narrador decide sobre Máculas por usar o poder.'),('Duração','Um turno para ativar; duração variável da doença.')]),
 ('Skuld Fulfilled','Destino de Skuld',5,[93],{},[
 ('Descrição','Faz retornar doenças curadas, fraturas consolidadas e a idade de carniçais protegidos pela vitae. Não funciona em vampiros e não exige contato com o alvo.'),('Custo','Dois Testes de Sangue.'),('Parada','Vigor + Oblívio contra Vigor × 2, ou Vigor + Fortitude para quem possui a Disciplina.'),('Sistema','O usuário cobre ambas as palmas e o rosto com sangue, lembrando o rosto do alvo. Se vencer a disputa, uma condição grave que a vítima já sofreu e superou retorna imediatamente, com todos os efeitos debilitantes: câncer tratado, osso quebrado, doença ou mesmo Praga Necrótica. O Narrador define efeitos severos, podendo usar a tabela de ferimentos incapacitantes do Livro Básico inglês, p. 303.\n\nNum carniçal, remove a imunidade ao envelhecimento e elimina toda a vitae do organismo; carniçais antigos podem morrer ou desintegrar-se no local. Numa vitória crítica, o usuário pode matar o alvo parando seu coração. Numa falha total, o vampiro não pode voltar a usar este poder naquele indivíduo.'),('Duração','Variável, conforme a condição possa ou não ser tratada.')]),
]
for en,pt,level,numbers,amalgam,pt_rows in data:
 candidate=next(row for row in candidates if row['book']=='players-guide-v5' and row['name']==en)
 id=candidate['id'];english=sections(extract('players-guide-v5',numbers,en.upper()))
 # The page-90 two-column table is embedded in Aura's extracted prose. Remove
 # its cells here and restore all of them as a table under Where the Veil Thins.
 if en=='Aura of Decay':
  for section in english:section['text']=re.sub(r'\n\nEffect Wraiths cannot cross.*?\n\nvampire’s activation',' vampire’s activation',section['text'],flags=re.S)
 if en=='Where the Veil Thins':
  english.append({'title':'Density of the Veil','text':'| Density | Possible causes | Effect |\n| --- | --- | --- |\n| Impenetrable | No deaths here; sacred ground | Wraiths cannot cross here |\n| Thick | A death long ago; a place of joy | No effect |\n| Thin | Recent death; melancholic mortals pass through | −1 Difficulty on Oblivion Ceremony rolls |\n| Frayed | A series of deaths; frequent Ceremonies | −2 Difficulty on Oblivion Ceremony rolls |\n| Absent | Split the Veil used here; wraiths regularly cross | −2 Difficulty on Ceremonies; wraiths pass freely between worlds; mortals suffer two Superficial Health damage that cannot be healed until they leave |'})
 # Some Amalgams occur at the start of a merged paragraph.
 for section in english:
  section['text']=re.sub(r'^Amalgam: (Auspex|Fortitude) [12]\s*','',section['text'])
 requirements='Oblivion '+str(level)+'.'+''.join(' Amalgam: '+{'Auspícios':'Auspex','Fortitude':'Fortitude'}[name]+' '+str(dots)+'.' for name,dots in amalgam.items())
 english.insert(1,{'title':'Requirements','text':requirements})
 portuguese=[{'title':title,'text':body} for title,body in pt_rows]
 portuguese.insert(1,{'title':'Requisitos','text':'Oblívio '+str(level)+'.'+''.join(' Amálgama: '+name+' '+str(dots)+'.' for name,dots in amalgam.items())})
 portuguese.append({'title':'Regras gerais de Oblívio nesta fonte','text':shared['general_pt'].format(lighting='Ambientes moderadamente iluminados impõem uma penalidade de um dado ao teste de Disciplina envolvido.')})
 english.append({'title':'General Oblivion rules in this source','text':shared['general_en'].format(lighting='Moderately lit rooms apply a one-die penalty to the Discipline roll involved.')})
 refs=sorted(set(numbers+[86,87]));source=next(row for row in manifest if row['id']=='players-guide-v5')
 version={'id':id+'-players-guide-v5','book':'players-guide-v5','level':level,'sourceTitle':'Guia do Jogador V5, PDF pp. '+', '.join(map(str,refs)),'sourceLanguage':'en','pdfSha256':source['sha256'],'pages':[{'pdfPage':n,'printedPage':n-2} for n in refs],'requirements':{'disciplines':{'Oblívio':level}|amalgam},'descriptions':{'pt-BR':portuguese,'en':english}}
 entry={'id':id,'kind':'power','names':{'pt-BR':pt,'en':en},'aliases':[pt,en],'discipline':'Oblívio','level':level,'versions':[version]}
 (repo/'scripts/reviewed-content'/f'{id}.json').write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
print('18 Player’s Guide Oblivion powers prepared; Ceremony review remains separate')
